deepml motion 0.3
module corpus.deepml_motion.example_03501
policy deterministic
policy no_network
skeleton Rig03501 { joint Root parent none joint Hip parent Root joint FootL parent Hip joint FootR parent Hip }
procedural animation Procedural03501 seed 3501 {
  trajectory = predict_trajectory(velocity, horizon=1.0s)
  match = motion_match(database="local:motions_0", trajectory=trajectory)
  constrain contact FootL to ground when phase < 0.5
  constrain contact FootR to ground when phase >= 0.5
}
layered state_machine Layers03501 { base: Locomotion upper: Gesture additive: Breathing }
synchronize Procedural03501 with scene.Actor16 and timeline.Sequence4

